INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('7f70a32a-9138-415d-bd27-f56ce3062fe6', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 2, 'O perdão como libertação', NULL, '{"intro": "O ressentimento \u00e9 uma pris\u00e3o que voc\u00ea constr\u00f3i para o outro e acaba morando nela.", "prayer": "Em sil\u00eancio, pronuncie: Eu o libero, eu me libero.", "practice": "Identifique uma pessoa ou situa\u00e7\u00e3o que voc\u00ea ainda carrega.", "reflection": "Perdoar n\u00e3o \u00e9 esquecer, \u00e9 tirar o peso do passado dos seus ombros.", "journal_prompt": "Qual peso voc\u00ea est\u00e1 pronto para soltar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;